exec(open('wk23c.py',encoding='utf-8').read().split('ms=run')[0])
ms=run("caps")
# rebalance to maximize min local km/day
def used(i): return [w for w,x in ms.items() if x==i]
def pdx(i,n):
  s=SI[i]; days=(s["tb"]-s["ta"]).total_seconds()/86400
  return (s["d"]-s["ded"]-n*R)/days
chg=True
while chg:
  chg=False
  for w in list(ms):
    i=ms[w]
    for j in weeks[w]["ov"]:
      if j==i or len(used(j))>=SI[j]["caps"]: continue
      ni,nj=len(used(i)),len(used(j))
      before=min(pdx(i,ni),pdx(j,nj)); after=min(pdx(i,ni-1),pdx(j,nj+1))
      if after>before+0.5: ms[w]=j; chg=True; break
WD=["Mo","Di","Mi","Do","Fr","Sa","So"]
HOCH={29:"Kiefersfelden 17.07. Mo 14:44 (A93, auf Route)",49:"Eugendorf 06.12. Mi 14:11 (44 km von Firma) + Kössen 09.12.",50:"Salzburg-Aiglhof 13.12. Mi 15:19 (36 km von Firma)"}
MITTEL={19:"Brixlegg 08.05. Mo 09:18 (auf Route)",30:"Brixlegg 27.07. Do 09:55 (auf Route)",37:"Saalfelden 12.09. Di 16:05 (nur Pass-Thurn-Variante)"}
