for w,W in enumerate(weeks):
  i=ms.get(w)
  if i is None: out.append((W,None,None,None)); continue
  s=SI[i]; lo=max(W["lo"],s["ta"]); hi=min(W["hi"],s["tb"])
  # window weekdays
  d0=lo; days=[]
  while d0<hi:
    if d0.weekday()<5 and wd_overlap(max(d0,lo),min(hi,D(d0.year,d0.month,d0.day)+T(days=1)))>=5: days.append(d0.date())
    d0=D(d0.year,d0.month,d0.day)+T(days=1)
  n=len(used(i)); pd=pdx(i,n)
  if W["kw"] in HOCH: p=("hoch",HOCH[W["kw"]])
  elif W["kw"] in (32,33): p=("niedrig","Aug.: 3.750 km bei nur 43,72 l Kartentankung – Fremdbetankung/Urlaub ungeklärt")
  elif W["kw"]==52: p=("niedrig","Weihnachtswoche (25./26.12. Feiertage); Intervall enthält Fahrt nach Feistritz/Drau (Ktn)")
  elif pd<20: p=("niedrig","Intervall %s–%s: nach %d Modellfahrt(en) bleiben nur %.0f km/Tag Lokalverkehr"%(s["ta"].strftime("%d.%m."),s["tb"].strftime("%d.%m."),n,pd))
  elif W["kw"] in MITTEL: p=("mittel",MITTEL[W["kw"]])
  else: p=("mittel","km-Kapazität ausreichend (Rest %.0f km/Tag), aber kein Ortsanker auf der Route"%pd)
  out.append((W,i,days,p))
for W,i,days,p in out:
  print(W["kw"],i,(days[0].strftime("%d.%m."),days[-1].strftime("%d.%m."),len(days)) if days else None,p)
for i,s in enumerate(SI):
  n=len(used(i)); print(i,s["ta"].strftime("%d.%m."),s["tb"].strftime("%d.%m."),s["d"],s["ded"],"caps",s["caps"],"n",n,"rest",round(s["d"]-s["ded"]-n*R,1),"pd",round(pdx(i,n),1))
import pickle; pickle.dump([(W["kw"],i,days,p) for W,i,days,p in out],open("wk23_final.pkl","wb"))
EOF
